// ─── CONFIG DEL MÓDULO ──────────────────────────────────────────────────────
// Todo sale de variables de entorno. Los defaults dejan el módulo andando sin
// configurar nada salvo NOTION_TICKETS_DATABASE_ID. Requiere en n8n:
// N8N_BLOCK_ENV_ACCESS_IN_NODE=false (leer $env dentro de nodos Code).
const ENV = (typeof $env !== 'undefined' && $env) ? $env : {};
const val = (k, def) => {
  let v;
  try { v = ENV[k]; } catch (e) { v = undefined; }
  return (v === undefined || v === null || v === '') ? def : String(v);
};
const lista = (k, def) => val(k, def).split(',').map((s) => s.trim()).filter(Boolean);
const mapa = (k, def) => {
  const out = {};
  for (const par of lista(k, def)) {
    const i = par.indexOf(':');
    if (i < 0) continue;
    out[par.slice(0, i).trim().toUpperCase()] = Number(par.slice(i + 1).trim());
  }
  return out;
};
const bool = (k, def) => val(k, def ? 'true' : 'false').toLowerCase() === 'true';

// Nombres de las propiedades en Notion. Se pueden remapear enteros con
// TICKETS_PROPS (JSON) para engancharse a una base que ya existe.
const PROPS = Object.assign({
  titulo: 'Name',
  estado: 'Estado',
  prioridad: 'Prioridad',
  prioridadInicial: 'Prioridad inicial',
  score: 'Score',
  etiquetas: 'Etiquetas',
  proyecto: 'Proyecto',
  origen: 'Origen',
  ref: 'Ref',
  creado: 'Creado',
  movimiento: 'Ultimo movimiento',
  escaladas: 'Escaladas',
  vence: 'Vence',
  notas: 'Notas',
}, JSON.parse(val('TICKETS_PROPS', '{}')));

const CFG = {
  databaseId: val('NOTION_TICKETS_DATABASE_ID', ''),
  proyecto: val('TICKETS_PROYECTO', 'CRM Freelance'),
  estados: lista('TICKETS_ESTADOS', 'BACKLOG,EN_CURSO,BLOQUEADO,HECHO'),
  estadosCerrados: lista('TICKETS_ESTADOS_CERRADOS', 'HECHO'),
  prioridades: lista('TICKETS_PRIORIDADES', 'BAJA,MEDIA,ALTA,CRITICA'),
  origenes: lista('TICKETS_ORIGENES', 'MANUAL,API,CRM,DASHBOARD'),
  // Días sin movimiento que tolera cada prioridad antes de subir un escalón.
  // Es el corazón del "que no quede en el olvido".
  diasEscalada: mapa('TICKETS_DIAS_ESCALADA', 'BAJA:10,MEDIA:7,ALTA:4'),
  pesoPrioridad: mapa('TICKETS_PESO_PRIORIDAD', 'BAJA:10,MEDIA:25,ALTA:50,CRITICA:80'),
  puntosPorDia: Number(val('TICKETS_PUNTOS_POR_DIA', '2')),
  scoreMax: Number(val('TICKETS_SCORE_MAX', '100')),
  filtrarPorProyecto: bool('TICKETS_FILTRAR_POR_PROYECTO', true),
  apiKey: val('TICKETS_API_KEY', ''),
  props: PROPS,
};
CFG.prioridadDefault = (function () {
  const p = val('TICKETS_PRIORIDAD_DEFAULT', 'MEDIA').toUpperCase();
  return CFG.prioridades.includes(p) ? p : CFG.prioridades[0];
})();
CFG.estadoInicial = (function () {
  const e = val('TICKETS_ESTADO_INICIAL', '').toUpperCase();
  return CFG.estados.includes(e) ? e : CFG.estados[0];
})();

// score = peso de la prioridad + puntos por cada día abierto (topeado).
// Así un ticket viejo de prioridad baja termina pesando más que uno nuevo.
const calcularScore = (prioridad, diasAbierto) => {
  const base = Number(CFG.pesoPrioridad[String(prioridad).toUpperCase()] || 0);
  const suma = CFG.puntosPorDia * Math.max(0, Number(diasAbierto) || 0);
  return Math.max(0, Math.min(CFG.scoreMax, Math.round(base + suma)));
};

const HOY = new Date().toISOString().slice(0, 10);
const diasDesde = (iso) => {
  if (!iso) return 0;
  const t = Date.parse(String(iso).length <= 10 ? String(iso) + 'T00:00:00Z' : iso);
  if (!Number.isFinite(t)) return 0;
  return Math.max(0, Math.floor((Date.parse(HOY + 'T00:00:00Z') - t) / 86400000));
};

// Si TICKETS_API_KEY está vacía el módulo queda abierto (útil en local).
const autorizado = (headers) => {
  if (!CFG.apiKey) return true;
  const h = headers || {};
  return String(h['x-api-key'] || h['X-API-Key'] || '') === CFG.apiKey;
};

const enLista = (v, opciones, def) => {
  const u = String(v == null ? '' : v).trim().toUpperCase();
  return opciones.includes(u) ? u : def;
};

// Lee una propiedad de una página de Notion sin importar su tipo.
const leerProp = (page, nombre) => {
  const p = (page && page.properties) ? page.properties[nombre] : null;
  if (!p) return null;
  if (p.type === 'title') return (p.title[0] || {}).plain_text || '';
  if (p.type === 'rich_text') return (p.rich_text[0] || {}).plain_text || '';
  if (p.type === 'select') return p.select ? p.select.name : null;
  if (p.type === 'multi_select') return p.multi_select.map((t) => t.name);
  if (p.type === 'number') return p.number;
  if (p.type === 'date') return p.date ? p.date.start : null;
  return null;
};

// Arma el filtro de Notion para "tickets abiertos de este proyecto".
const filtroAbiertos = (proyecto) => {
  const f = [];
  if (CFG.filtrarPorProyecto && proyecto) {
    f.push({ property: CFG.props.proyecto, select: { equals: String(proyecto) } });
  }
  for (const e of CFG.estadosCerrados) {
    f.push({ property: CFG.props.estado, select: { does_not_equal: e } });
  }
  return f;
};
// ─── FIN CONFIG ─────────────────────────────────────────────────────────────

// Valida el POST /webhook/ticket/nuevo y arma el body de creación de Notion.
// Salida: { ok:true, notion_body } o { ok:false, http_code, error }.
