  return [{ json: { ok: false, http_code: 500, error: 'Falta la variable de entorno NOTION_TICKETS_DATABASE_ID.' } }];
}

const titulo = String(body.titulo || body.title || '').trim();
if (!titulo) {
  return [{ json: { ok: false, http_code: 400, error: 'Falta "titulo": el ticket describe una tarea pendiente.' } }];
}

const prioridad = enLista(body.prioridad, CFG.prioridades, CFG.prioridadDefault);
const estado = enLista(body.estado, CFG.estados, CFG.estadoInicial);
const origen = enLista(body.origen, CFG.origenes, 'API');
const proyecto = String(body.proyecto || CFG.proyecto).trim().slice(0, 100);

const crudas = Array.isArray(body.etiquetas) ? body.etiquetas : String(body.etiquetas || '').split(',');
const etiquetas = crudas.map((t) => String(t).trim()).filter(Boolean).slice(0, 10);

const P = CFG.props;
const properties = {};
properties[P.titulo] = { title: [{ text: { content: titulo.slice(0, 200) } }] };
properties[P.estado] = { select: { name: estado } };
properties[P.prioridad] = { select: { name: prioridad } };
properties[P.prioridadInicial] = { select: { name: prioridad } };
properties[P.score] = { number: calcularScore(prioridad, 0) };
properties[P.escaladas] = { number: 0 };
properties[P.proyecto] = { select: { name: proyecto } };
properties[P.origen] = { select: { name: origen } };
properties[P.creado] = { date: { start: HOY } };
properties[P.movimiento] = { date: { start: HOY } };
if (etiquetas.length) properties[P.etiquetas] = { multi_select: etiquetas.map((n) => ({ name: n.slice(0, 100) })) };
if (body.ref) properties[P.ref] = { rich_text: [{ text: { content: String(body.ref).slice(0, 200) } }] };
if (body.notas) properties[P.notas] = { rich_text: [{ text: { content: String(body.notas).slice(0, 1800) } }] };
if (body.vence) properties[P.vence] = { date: { start: String(body.vence).slice(0, 10) } };

return [{
  json: {
    ok: true,
    titulo,
    estado,
    prioridad,
    proyecto,
    etiquetas,
    notion_body: { parent: { database_id: CFG.databaseId }, properties },
  },
}];

