  puntosPorDia: Number(val('TICKETS_PUNTOS_POR_DIA', '2')),
  scoreMax: Number(val('TICKETS_SCORE_MAX', '100')),
  filtrarPorProyecto: bool('TICKETS_FILTRAR_POR_PROYECTO', true),
  apiKey: val('TICKETS_API_KEY', ''),
  props: PROPS,
};
CFG.prioridadDefault = (function () {
  const p = val('TICKETS_PRIORIDAD_DEFAULT', 'MEDIA').toUpperCase();
  return CFG.prioridades.includes(p) ? p : CFG.prioridades[0];
})();
CFG.estadoInicial = (function () {
  const e = val('TICKETS_ESTADO_INICIAL', '').toUpperCase();
  return CFG.estados.includes(e) ? e : CFG.estados[0];
})();

// score = peso de la prioridad + puntos por cada día abierto (topeado).
// Así un ticket viejo de prioridad baja termina pesando más que uno nuevo.
const calcularScore = (prioridad, diasAbierto) => {
  const base = Number(CFG.pesoPrioridad[String(prioridad).toUpperCase()] || 0);
  const suma = CFG.puntosPorDia * Math.max(0, Number(diasAbierto) || 0);
  return Math.max(0, Math.min(CFG.scoreMax, Math.round(base + suma)));
};

const HOY = new Date().toISOString().slice(0, 10);
const diasDesde = (iso) => {
  if (!iso) return 0;
  const t = Date.parse(String(iso).length <= 10 ? String(iso) + 'T00:00:00Z' : iso);
  if (!Number.isFinite(t)) return 0;
  return Math.max(0, Math.floor((Date.parse(HOY + 'T00:00:00Z') - t) / 86400000));
};

// Si TICKETS_API_KEY está vacía el módulo queda abierto (útil en local).
const autorizado = (headers) => {
  if (!CFG.apiKey) return true;
  const h = headers || {};
  return String(h['x-api-key'] || h['X-API-Key'] || '') === CFG.apiKey;
};

const enLista = (v, opciones, def) => {
  const u = String(v == null ? '' : v).trim().toUpperCase();
  return opciones.includes(u) ? u : def;
};

// Lee una propiedad de una página de Notion sin importar su tipo.
const leerProp = (page, nombre) => {
  const p = (page && page.properties) ? page.properties[nombre] : null;
  if (!p) return null;
  if (p.type === 'title') return (p.title[0] || {}).plain_text || '';
  if (p.type === 'rich_text') return (p.rich_text[0] || {}).plain_text || '';
  if (p.type === 'select') return p.select ? p.select.name : null;
  if (p.type === 'multi_select') return p.multi_select.map((t) => t.name);
  if (p.type === 'number') return p.number;
  if (p.type === 'date') return p.date ? p.date.start : null;
  return null;
};

// Arma el filtro de Notion para "tickets abiertos de este proyecto".
const filtroAbiertos = (proyecto) => {
  const f = [];
  if (CFG.filtrarPorProyecto && proyecto) {
    f.push({ property: CFG.props.proyecto, select: { equals: String(proyecto) } });
  }
  for (const e of CFG.estadosCerrados) {
    f.push({ property: CFG.props.estado, select: { does_not_equal: e } });
  }
  return f;
};
// ─── FIN CONFIG ─────────────────────────────────────────────────────────────

// ─── ENVEJECIMIENTO ─────────────────────────────────────────────────────────
// Regla: un ticket que lleva más de TICKETS_DIAS_ESCALADA[prioridad] días sin
// movimiento sube un escalón de prioridad. Aunque haya entrado como BAJA, si
// nadie lo toca termina en CRITICA — eso es lo que evita que quede en el olvido.
// El score además crece solo con los días abiertos, así el orden del tablero
// se reacomoda sin intervención.
const evaluarTickets = (paginas) => {
  const P = CFG.props;
  const cambios = [];

  for (const page of (paginas || [])) {
    const prioridad = String(leerProp(page, P.prioridad) || CFG.prioridadDefault).toUpperCase();
    const creado = leerProp(page, P.creado) || page.created_time;
    const movimiento = leerProp(page, P.movimiento) || creado;
    const diasAbierto = diasDesde(creado);
    const diasQuieto = diasDesde(movimiento);

    const idx = CFG.prioridades.indexOf(prioridad);
    const umbral = CFG.diasEscalada[prioridad];
    const puedeSubir = idx >= 0 && idx < CFG.prioridades.length - 1 && Number.isFinite(umbral);
    const sube = puedeSubir && diasQuieto >= umbral;
    const nuevaPrioridad = sube ? CFG.prioridades[idx + 1] : prioridad;
    const nuevoScore = calcularScore(nuevaPrioridad, diasAbierto);
    const scoreActual = Number(leerProp(page, P.score));

    // Si no sube y el score ya está bien, no gastamos una llamada a la API.
    if (!sube && Number.isFinite(scoreActual) && scoreActual === nuevoScore) continue;

    const properties = {};
    properties[P.score] = { number: nuevoScore };
    if (sube) {
      properties[P.prioridad] = { select: { name: nuevaPrioridad } };
      properties[P.escaladas] = { number: Number(leerProp(page, P.escaladas) || 0) + 1 };
      properties[P.movimiento] = { date: { start: HOY } };
    }

    cambios.push({
      ticket_id: page.id,
      url: page.url || null,
      titulo: leerProp(page, P.titulo) || '(sin título)',
      estado: leerProp(page, P.estado) || CFG.estadoInicial,
      sube,
      prioridad_previa: prioridad,
      prioridad: nuevaPrioridad,
      score_previo: Number.isFinite(scoreActual) ? scoreActual : null,
      score: nuevoScore,
      dias_abierto: diasAbierto,
      dias_quieto: diasQuieto,
      notion_patch: { properties },
    });
  }

  return cambios;
};
// ─── FIN ENVEJECIMIENTO ─────────────────────────────────────────────────────

// Arma el aviso diario por Telegram. Corre en paralelo a los PATCH: calcula
// las mismas escaladas sobre los mismos datos, así el mensaje refleja lo que
// el cron acaba de aplicar.
const res = $input.first().json || {};
const paginas = Array.isArray(res.results) ? res.results : [];
const P = CFG.props;
const cambios = evaluarTickets(paginas);
const escalados = cambios.filter((c) => c.sube);

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const topePrioridad = CFG.prioridades[CFG.prioridades.length - 1];

// Los que ya llegaron al tope de la escala y siguen sin resolverse.
const criticos = paginas
  .filter((p) => String(leerProp(p, P.prioridad) || '').toUpperCase() === topePrioridad)
  .map((p) => ({
    titulo: leerProp(p, P.titulo) || '(sin título)',
    dias: diasDesde(leerProp(p, P.movimiento) || leerProp(p, P.creado) || p.created_time),
  }))
  .sort((a, b) => b.dias - a.dias)
  .slice(0, 5);

const lineas = [];
lineas.push('🎫 <b>Tickets — ' + esc(CFG.proyecto) + '</b>');
lineas.push('Abiertos: <b>' + paginas.length + '</b>');

if (escalados.length) {
  lineas.push('');
  lineas.push('⬆️ <b>Subieron de prioridad (' + escalados.length + ')</b>');
  for (const t of escalados.slice(0, 10)) {
    lineas.push('• ' + esc(t.titulo) + ' — ' + t.prioridad_previa + ' → <b>' + t.prioridad + '</b> (' + t.dias_quieto + 'd sin mover)');
  }
  if (escalados.length > 10) lineas.push('… y ' + (escalados.length - 10) + ' más.');
}

if (criticos.length) {
  lineas.push('');
  lineas.push('🔥 <b>En ' + topePrioridad + ' sin resolver</b>');
  for (const t of criticos) {
    lineas.push('• ' + esc(t.titulo) + ' (' + t.dias + 'd)');
  }
}

if (!escalados.length && !criticos.length && paginas.length) {
  lineas.push('');
  lineas.push('✅ Nada escaló hoy, el tablero está al día.');
}

return [{
  json: {
    // Sin tickets abiertos no molestamos; tampoco si no hay nada nuevo que decir.
    hay_aviso: paginas.length > 0 && (escalados.length > 0 || criticos.length > 0),
    abiertos: paginas.length,
    escalados: escalados.length,
    criticos: criticos.length,
    texto: lineas.join('\n'),
  },
}];
